(132, 4, 'funfactarea', 'Funfact Area', '<svg xmlns=\"http://www.w3.org/2000/svg\" \r\n height=\"50px\">\r\n  <!-- Embedding an image -->\r\n  <image xlink:href=\"https://test.webfire.in/public/admin/theme/img/user.jpg\" width=\"100%\" height=\"100%\" />\r\n</svg>', '{class : \'\',id:\'\'}', '<div class=\"funfact-area pb-75\">\r\n            <div class=\"container\">\r\n                <div class=\"row g-0 justify-content-center\" data-cues=\"slideInUp\" data-disabled=\"true\">\r\n                    <div class=\"col-lg-4 col-sm-6 col-md-6\" data-cue=\"slideInUp\" data-show=\"true\" style=\"animation-name: slideInUp; animation-duration: 600ms; animation-timing-function: ease; animation-delay: 0ms; animation-direction: normal; animation-fill-mode: both;\">\r\n                        <div class=\"single-funfact-info text-center\">\r\n                            <h2 class=\"d-flex align-items-center justify-content-center\">\r\n                                <i class=\"flaticon-mortarboard\"></i>\r\n                                <span class=\"counter\">124</span>\r\n                                +\r\n                            </h2>\r\n                            <p>We Have online Programs</p>\r\n                            <a class=\"text-decoration-none arrow-btn\" href=\"program-details.html\">\r\n                                Know More\r\n                                <i class=\"flaticon-right-arrow\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-lg-4 col-sm-6 col-md-6\" data-cue=\"slideInUp\" data-show=\"true\" style=\"animation-name: slideInUp; animation-duration: 600ms; animation-timing-function: ease; animation-delay: 180ms; animation-direction: normal; animation-fill-mode: both;\">\r\n                        <div class=\"single-funfact-info text-center\">\r\n                            <h2 class=\"d-flex align-items-center justify-content-center\">\r\n                                <i class=\"flaticon-book\"></i>\r\n                                <span class=\"counter\">393</span>\r\n                                +\r\n                            </h2>\r\n                            <p>We have the best Courses</p>\r\n                            <a class=\"text-decoration-none arrow-btn\" href=\"program-details.html\">\r\n                                Know More\r\n                                <i class=\"flaticon-right-arrow\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-lg-4 col-sm-6 col-md-6\" data-cue=\"slideInUp\" data-show=\"true\" style=\"animation-name: slideInUp; animation-duration: 600ms; animation-timing-function: ease; animation-delay: 360ms; animation-direction: normal; animation-fill-mode: both;\">\r\n                        <div class=\"single-funfact-info text-center\">\r\n                            <h2 class=\"d-flex align-items-center justify-content-center\">\r\n                                <i class=\"flaticon-graduate\"></i>\r\n                                <span class=\"counter\">865</span>\r\n                                +\r\n                            </h2>\r\n                            <p>Adma Has Professional Teacher</p>\r\n                            <a class=\"text-decoration-none arrow-btn\" href=\"program-details.html\">\r\n                                Know More\r\n                                <i class=\"flaticon-right-arrow\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>', '1', 999, 14, '2023-10-16 21:34:21', '2024-09-01 13:43:14'),
(133, 4, 'applyarea', 'Apply area', '<svg xmlns=\"http://www.w3.org/2000/svg\" \r\n height=\"50px\">\r\n  <!-- Embedding an image -->\r\n  <image xlink:href=\"https://test.webfire.in/public/admin/theme/img/user.jpg\" width=\"100%\" height=\"100%\" />\r\n</svg>', '{class : \'\',id:\'\'}', '<div class=\"apply-area pt-100 pb-75\">\r\n    <div class=\"container\">\r\n        <div class=\"row align-items-center\" data-cues=\"slideInUp\" data-disabled=\"true\">\r\n            <div class=\"col-lg-6\" data-cue=\"slideInUp\" data-show=\"true\" style=\"animation-name: slideInUp; animation-duration: 600ms; animation-timing-function: ease; animation-delay: 0ms; animation-direction: normal; animation-fill-mode: both;\">\r\n                <div class=\"apply-image\">\r\n                    <div class=\"image\">\r\n                        <img src=\"/public/theme/college/assets/img/apply/apply-1.jpg\" alt=\"apply-image\">\r\n                    </div>\r\n                    <div class=\"user-help d-flex align-items-center\">\r\n                        <a class=\"icon text-decoration-none\" href=\"tel:45993939990\">\r\n                            <i class=\"ri-phone-line\"></i>\r\n                        </a>\r\n                        <div class=\"content\">\r\n                            <span>For Help</span>\r\n                            <a class=\"text-decoration-none d-block\" href=\"tel:45993939990\">\r\n                                +459 9393 9990\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-lg-6\" data-cue=\"slideInUp\" data-show=\"true\" style=\"animation-name: slideInUp; animation-duration: 600ms; animation-timing-function: ease; animation-delay: 0ms; animation-direction: normal; animation-fill-mode: both;\">\r\n                <div class=\"apply-content\">\r\n                    <div class=\"title\">\r\n                        <h2>How To Apply At Adma</h2>\r\n                    </div>\r\n                    <div class=\"apply-content-card d-flex\">\r\n                        <div class=\"icon\">\r\n                            <i class=\"flaticon-writing\"></i>\r\n                        </div>\r\n                        <div class=\"content\">\r\n                            <h3>\r\n                                <span>01.</span>\r\n                                Complete Application Form\r\n                            </h3>\r\n                            <p>Furthermore, our university campus provides a vibrant &amp; supportive community that embraces diversity and fosters inclusivity.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"apply-content-card d-flex\">\r\n                        <div class=\"icon\">\r\n                            <i class=\"flaticon-search-3\"></i>\r\n                        </div>\r\n                        <div class=\"content\">\r\n                            <h3>\r\n                                <span>02.</span>\r\n                                Application Review\r\n                            </h3>\r\n                            <p>We believe that a diverse student body enhances the learning experience and prepares students to thrive in a globalized world.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"apply-content-card mb-0 border-bottom-0 d-flex\">\r\n                        <div class=\"icon\">\r\n                            <i class=\"flaticon-loan\"></i>\r\n                        </div>\r\n                        <div class=\"content\">\r\n                            <h3>\r\n                                <span>03.</span>\r\n                                Payment of Fees\r\n                            </h3>\r\n                            <p>As a student at Adma, you will have access to state-of-the-art facilities, cutting-edge research laboratories, &amp; an extensive library.</p>\r\n                        </div>\r\n                    </div>\r\n                    <ul class=\"list-unstyled ps-0 mb-0 apply-btn\">\r\n                        <li class=\"d-inline-block\">\r\n                            <a class=\"text-decoration-none default-btn\" href=\"application.html\">\r\n                                Application Form\r\n                                <i class=\"flaticon-right-arrow\"></i>\r\n                            </a>\r\n                        </li>\r\n                        <li class=\"d-inline-block\">\r\n                            <ul class=\"list-unstyled d-flex align-items-center ps-0 mb-0 play-btn\">\r\n                                <li>\r\n                                    <a class=\"text-decoration-none icon\" data-fslightbox=\"gallery\" href=\"https://www.youtube.com/watch?v=3nQNiWdeH2Q\">\r\n                                        <i class=\"ri-play-mini-fill\"></i>\r\n                                    </a>\r\n                                </li>\r\n                                <li> \r\n                                    <a class=\"text-decoration-none arrow-btn\" data-fslightbox=\"gallery\" href=\"https://www.youtube.com/watch?v=3nQNiWdeH2Q\">\r\n                                        See How To Apply\r\n                                        <i class=\"flaticon-right-arrow\"></i>\r\n                                    </a>\r\n                                </li>\r\n                            </ul>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>', '1', 999, 14, '2023-10-16 21:34:21', '2024-09-01 13:43:14'),
