      </div>\r\n                            <div class=\"swiper-slide\">\r\n                                <div class=\"single-partner-logo\">\r\n                                    <img src=\"assets/img/partner/partner-2.png\" alt=\"partner-logo\">\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"swiper-slide\">\r\n                                <div class=\"single-partner-logo\">\r\n                                    <img src=\"assets/img/partner/partner-3.png\" alt=\"partner-logo\">\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"swiper-slide\">\r\n                                <div class=\"single-partner-logo\">\r\n                                    <img src=\"assets/img/partner/partner-4.png\" alt=\"partner-logo\">\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"swiper-slide\">\r\n                                <div class=\"single-partner-logo\">\r\n                                    <img src=\"assets/img/partner/partner-5.png\" alt=\"partner-logo\">\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <!-- End Partner Area -->\r\n\r\n        <!-- Start Overview Area -->\r\n        <div class=\"overview-area pb-75\">\r\n            <div class=\"container\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-lg-6\">\r\n                        <div class=\"overview-content\">\r\n                            <div class=\"image\">\r\n                                <img src=\"assets/img/overview/overview-1.jpg\" alt=\"overview-image\">\r\n                            </div>\r\n                            <div class=\"row align-items-center\" data-cues=\"slideInUp\">\r\n                                <div class=\"col-lg-6 col-sm-6 col-md-6\">\r\n                                    <div class=\"graduets-counter\">\r\n                                        <h2 class=\"d-flex align-items-center\">\r\n                                            <img src=\"assets/img/graduets/graduets-5.svg\" alt=\"graduets-svg\">\r\n                                            <span class=\"counter\">124</span>\r\n                                            +\r\n                                        </h2>\r\n                                        <p>Our graduates programs</p>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"col-lg-6 col-sm-6 col-md-6\">\r\n                                    <div class=\"graduets-btn text-end\">\r\n                                        <a class=\"text-decoration-none arrow-btn\" href=\"programs.html\">\r\n                                            More Graduates Programs\r\n                                            <i class=\"flaticon-right-arrow\"></i>\r\n                                        </a>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-lg-6\">\r\n                        <div class=\"overview-image\">\r\n                            <div class=\"title\">\r\n                                <h2 class=\"d-flex align-items-center\">\r\n                                    <img src=\"assets/img/title-shape.svg\" alt=\"title-shape\">\r\n                                    About Adma University\r\n                                </h2>\r\n                                <p>At Adma, we believe in providing an exceptional educational experienc that prepares students for success in an ever-changing world. As a leading institution of higher learning,</p>\r\n                                <p>we are committed to fostering a vibrant academic community and empowering our students to reach their full potential.</p>\r\n                            </div>\r\n                            <a class=\"text-decoration-none arrow-btn\" href=\"university-overview.html\">\r\n                                University Overview\r\n                                <i class=\"flaticon-right-arrow\"></i>\r\n                            </a>\r\n                            <div class=\"casual-image pages-style \">\r\n                                <img src=\"assets/img/overview/overview-2.jpg\" alt=\"overview-image\">\r\n                                <div class=\"content-shape\">\r\n                                    <img src=\"assets/img/hero/banner-wrap-city-3.png\" alt=\"banner-wrap-shape\">\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <!-- End Overview Area -->\r\n\r\n        <!-- Start Funfact Area -->\r\n        <div class=\"funfact-area pb-75\">\r\n            <div class=\"container\">\r\n                <div class=\"row g-0 justify-content-center\" data-cues=\"slideInUp\">\r\n                    <div class=\"col-lg-4 col-sm-6 col-md-6\">\r\n                        <div class=\"single-funfact-info text-center\">\r\n                            <h2 class=\"d-flex align-items-center justify-content-center\">\r\n                                <i class=\"flaticon-mortarboard\"></i>\r\n                                <span class=\"counter\">124</span>\r\n                                +\r\n                            </h2>\r\n                            <p>We Have online Programs</p>\r\n                            <a class=\"text-decoration-none arrow-btn\" href=\"program-details.html\">\r\n                                Know More\r\n                                <i class=\"flaticon-right-arrow\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-lg-4 col-sm-6 col-md-6\">\r\n                        <div class=\"single-funfact-info text-center\">\r\n                            <h2 class=\"d-flex align-items-center justify-content-center\">\r\n                                <i class=\"flaticon-book\"></i>\r\n                                <span class=\"counter\">391</span>\r\n                                +\r\n                            </h2>\r\n                            <p>We have the best courses</p>\r\n                            <a class=\"text-decoration-none arrow-btn\" href=\"program-details.html\">\r\n                                Know More\r\n                                <i class=\"flaticon-right-arrow\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-lg-4 col-sm-6 col-md-6\">\r\n                        <div class=\"single-funfact-info text-center\">\r\n                            <h2 class=\"d-flex align-items-center justify-content-center\">\r\n                                <i class=\"flaticon-graduate\"></i>\r\n                                <span class=\"counter\">881</span>\r\n                                +\r\n                            </h2>\r\n                            <p>Adma Has Professional Teacher</p>\r\n                            <a class=\"text-decoration-none arrow-btn\" href=\"program-details.html\">\r\n                                Know More\r\n                                <i class=\"flaticon-right-arrow\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <!-- End Funfact Area -->\r\n\r\n        <!-- Start Facilities Area