INSERT INTO `ab_blocks_old` (`id`, `category_id`, `blockid`, `label`, `media`, `attributes`, `content`, `status`, `seq`, `theme_id`, `created_at`, `updated_at`) VALUES
(54, 2, 'box-icon-1', 'Box Icon 1', '<svg xmlns=\"http://www.w3.org/2000/svg\" \r\n height=\"50px\">\r\n  <!-- Embedding an image -->\r\n  <image xlink:href=\"https://test.webfire.in/public/admin/theme/img/user.jpg\" width=\"100%\" height=\"100%\" />\r\n</svg>', '{class : \'\',id:\'\'}', '<div class=\"feature-icon-wrapper section-space--ptb_100\">\n                <div class=\"container\">\n\n                    <div class=\"row\">\n                        <div class=\"col-lg-12\">\n                            <div class=\"section-title-wrap text-center section-space--mb_40\">\n                                <h6 class=\"section-sub-title mb-20\">Industries we Serve</h6>\n                                <h3 class=\"heading\">For your very specific industry, <br> we have <span class=\"text-color-primary\"> highly-tailored IT solutions.</span></h3>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"row\">\n                        <div class=\"col-12\">\n                            <div class=\"feature-list__one\">\n                                <div class=\"row\">\n\n                                    <div class=\"col-lg-3 col-md-6\">\n                                        <!-- ht-box-icon Start -->\n                                        <div class=\"ht-box-icon style-01 single-svg-icon-box\">\n                                            <div class=\"icon-box-wrap\">\n                                                <div class=\"icon\">\n\n                                                    <!--<img src=\"assets/images/svg/linea-basic-heart.svg\" alt=\"\">-->\n\n                                                    <div class=\"svg-icon\" id=\"svg-icon-1\" data-svg-icon=\"assets/images/svg/linea-basic-heart.svg\"><svg version=\"1.1\" id=\"Layer_1\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" x=\"0px\" y=\"0px\" width=\"100%\" height=\"100%\" viewB