(62, 2, 'popup-video', 'Popup Video', '<svg xmlns=\"http://www.w3.org/2000/svg\" \r\n height=\"50px\">\r\n  <!-- Embedding an image -->\r\n  <image xlink:href=\"https://test.webfire.in/public/admin/theme/img/user.jpg\" width=\"100%\" height=\"100%\" />\r\n</svg>', '{class : \'\',id:\'\'}', '<div class=\"popup-video-wrapper section-space--pb_120 section-space--pt_90 \">\r\n                <div class=\"container\">\r\n                    <div class=\"row\">\r\n                        <div class=\"col-lg-6 video-popup text-center wow move-up animated\" style=\"visibility: visible;\">\r\n                            <a href=\"https://www.youtube.com/watch?v=9No-FiEInLA\" class=\"video-link mt-30\">\r\n                                <div class=\"single-popup-wrap\">\r\n                                    <img class=\"img-fluid\" src=\"assets/images/bg/home-processing-video-intro-slider-slide-01-image-01-570x420.webp\" alt=\"\">\r\n                                    <div class=\"ht-popup-video video-overlay\">\r\n                                        <div class=\"video-button__one\">\r\n                                            <div class=\"video-play\">\r\n                                                <span class=\"video-play-icon\"></span>\r\n                                            </div>\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n                            </a>\r\n                        </div>\r\n                        <div class=\"col-lg-6 video-popup text-center wow move-up animated\" style=\"visibility: visible;\">\r\n                            <a href=\"https://www.youtube.com/watch?v=9No-FiEInLA\" class=\"video-link  mt-30\">\r\n                                <div class=\"single-popup-wrap\">\r\n                                    <img class=\"img-fluid\" src=\"assets/images/bg/home-processing-video-intro-slider-slide-01-image-01-570x420.webp\" alt=\"\">\r\n                                    <div class=\"ht-popup-video video-button\">\r\n                                        <div class=\"video-mark\">\r\n                                            <div class=\"wave-pulse wave-pulse-1\"></div>\r\n                                            <div class=\"wave-pulse wave-pulse-2\"></div>\r\n                                        </div>\r\n                                        <div class=\"video-button__two\">\r\n                                            <div class=\"video-play\">\r\n                                                <span class=\"video-play-icon\"></span>\r\n                                            </div>\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>', '1', 999, 7, '2023-10-16 21:34:21', '2024-02-27 06:50:20'),
(63, 2, 'pricing-box', 'Pricing Box', '<svg xmlns=\"http://www.w3.org/2000/svg\" \r\n height=\"50px\">\r\n  <!-- Embedding an image -->\r\n  <image xlink:href=\"https://test.webfire.in/public/admin/theme/img/user.jpg\" width=\"100%\" height=\"100%\" />\r\n</svg>', '{class : \'\',id:\'\'}', '<div class=\"site-wrapper-reveal\">\r\n\r\n            <!--========= Pricing Table Area Start ==========-->\r\n            <div class=\"pricing-table-area section-space--ptb_100 bg-gray\">\r\n                <div class=\"pricing-table-title-area position-relative\">\r\n                    <div class=\"container\">\r\n                        <div class=\"row\">\r\n                            <div class=\"col-lg-12\">\r\n                                <div class=\"section-title-wrapper text-center section-space--mb_60 wow move-up animated\" style=\"visibility: visible;\">\r\n                                    <h6 class=\"section-sub-title mb-20\">Pricing and plan</h6>\r\n                                    <h3 class=\"section-title\">1 monthly fee for <span class=\"text-color-primary\">all IT services.</span> </h3>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"pricing-table-content-area\">\r\n                    <div class=\"container\">\r\n                        <div class=\"row pricing-table-one\">\r\n                            <div class=\"col-12 col-md-6 col-lg-4 col-xl-4 pricing-table wow move-up animated\" style=\"visibility: visible;\">\r\n                                <div class=\"pricing-table__inner\">\r\n                                    <div class=\"pricing-table__header\">\r\n                                        <h6 class=\"sub-title\">Basic</h6>\r\n                                        <div class=\"pricing-table__image\">\r\n                                            <img src=\"assets/images/icons/mit