-image:linear-gradient(#0b003f 0%, #0b003f 100%);}#io44xq:hover{background-repeat:repeat;background-position:left top;background-attachment:scroll;background-size:auto;background-image:linear-gradient(#0b003f 0%, #0b003f 100%);}#i5frww:hover{background-repeat:repeat;background-position:left top;background-attachment:scroll;background-size:auto;background-image:linear-gradient(#0b003f 0%, #0b003f 100%);}#in49ok:hover{background-repeat:repeat;background-position:left top;background-attachment:scroll;background-size:auto;background-image:linear-gradient(#0b003f 0%, #0b003f 100%);}#i54l4j{width:100%;}#iq3usy{width:100%;}#id04ci{width:100%;}#i0re8k{width:100%;}#i82uwf{width:100%;}#iw8eo8{width:100%;}#i145g9{background-repeat:no-repeat;background-position:left top;background-attachment:fixed;background-size:cover;background-image:url(&#039;https://png.pngtree.com/background/20230626/original/pngtree-dark-concept-design-of-classic-architecture-living-room-interior-in-3d-picture-image_4058538.jpg&#039;);}@media (max-width: 480px){#im0ogh{margin:0px 0px 0px 12px;}#ia91mg{margin:0px 0px 0px 4px;}#iab0ei{margin:0px 0px 0px 21px;}#imhnet{margin:0px 0px 0px 13px;}}', '&lt;div id=&quot;main-wrapper&quot;&gt;&lt;div class=&quot;site-wrapper-reveal&quot;&gt;&lt;!--===========  feature-images-wrapper  Start =============--&gt;&lt;div class=&quot;feature-images-wrapper position-relative&quot;&gt;&lt;div class=&quot;swiper-container service-slider__container&quot;&gt;&lt;/div&gt;&lt;/div&gt;&lt;!--===========  feature-images-wrapper  End =============--&gt;&lt;!--======== Preview Item Page section Start ============--&gt;&lt;!--======== Preview Item Page section End ============--&gt;&lt;!--======== Preview RTL section Start ============--&gt;&lt;!--======== Preview RTL section End ============--&gt;&lt;!--======= Layouts section Start =======--&gt;&lt;div id=&quot;ivwdie&quot;&gt;[AB-Slider id=25]&lt;/div&gt;&lt;div id=&quot;i4npzk&quot; class=&quot;layouts-section-wrap section-space