(86, 95, '* { box-sizing: border-box; } body {margin: 0;}*{box-sizing:border-box;}body{margin:0;}#main-wrapper &gt; .site-wrapper-reveal &gt; .preview-hero-area.preview-hero-bg.position-relative.section-space--ptb_120{background-color:#c00707;color:#7a4848;}#iawi{visibility:visible;}#ivgxy8{margin:0px 0px 0px 1px;}#icjkcw{font-size:18px;color:#000000;text-align:justify;}#igl5b2{color:#e80404;}#iqgwfj{color:#000000;font-family:Impact, Charcoal, sans-serif;font-size:42px;}#inrprs{background-repeat:repeat;background-position:left top;background-attachment:scroll;background-size:auto;background-image:linear-gradient(#000000 0%, #000000 100%);}#ih5n7f{color:#000000;font-size:20px;}#ich7pe{visibility:visible;}#ic1nw3{visibility:visible;}#i0ymch{visibility:visible;}#ijukjb{visibility:visible;}#in8jtk{background-repeat:repeat;background-position:left top;background-attachment:scroll;background-size:auto;background-image:linear-gradient(#000000 0%, #000000 100%);}#i6mwey{margin:0px 0px 0px 1px;}#ibn54h{background-repeat:no-repeat;background-position:right center;background-attachment:fixed;background-size:cover;background-image:url(&#039;https://www.m1xchange.com/thought-xchange/wp-content/uploads/2023/09/shutterstock_2139780347-scaled.jpg&#039;);}#ipikoh{font-size:20px;color:#000000;}#itb6md{background-repeat:repeat;background-position:left top;background-attachment:scroll;background-size:auto;background-image:linear-gradient(#000000 0%, #000000 100%);}#ii2twn{margin:0px 0px 0px 1px;}#ik8n{margin:0px 0px 0px 1px;}#ikfump{font-size:50px;font-family:Impact, Charcoal, sans-serif;color:#fdfdfd;}#ir6sxa{color:rgb(253, 253, 253);font-family:Impact, Charcoal, sans-serif;font-size:50px;}#i8na{background-repeat:no-repeat;background-position:center center;background-attachment:fixed;background-size:cover;background-image:url(&#039;https://moolah.co.ke/wp-content/uploads/2024/05/Website-1600px-X-900-px-55-960x540.jpg&#039;);}#ip37h9{visibility:visible;}#ig0rla{visibility:visible;}#ivlpmc{visibility:visible;}#iu3f9i{width:100%;height:200px;}#iu3f9i-2{width:100%;height:200px;}#i5knaf{width:100%;height:200px;}#i6os9l{text-align:center;}#iep91k{text-align:center;}#i43ljx{text-align:center;}#iu3f9i-3{width:100%;}', '&lt;div id=&quot;main-wrapper&quot;&gt;&lt;div class=&quot;site-wrapper-reveal&quot;&gt;&lt;div data-aos=&quot;zoom-in-up&quot; id=&quot;i8na&quot; class=&quot;preview-hero-area preview-hero-bg position-relative section-space--ptb_120&quot;&gt;&lt;div id=&quot;iy1s&quot; class=&quot;container-fluid container-fluid--cp-150&quot;&gt;&lt;div id=&quot;ik8n&quot; class=&quot;row align-items-center&quot;&gt;&lt;div class=&quot;col-lg-6&quot;&gt;&lt;p id=&quot;ikfump&quot;&gt;Welcome to &lt;/p&gt;&lt;div id=&quot;iawi&quot; class=&quot;preview-hero-text wow move-up animated&quot;&gt;&lt;h2 id=&quot;id3nf&quot; class=&quot;font-weight--reguler text-white mb-30&quot;&gt;&lt;span id=&quot;ir6sxa&quot;&gt;Subrat Financial &amp;amp; Insurance Services&lt;/span&gt;&lt;/h2&gt;&lt;div class=&quot;hero-button mt-40&quot;&gt;&lt;a href=&quot;#section-demos&quot; id=&quot;i64xo&quot; class=&quot;btn btn--white&quot;&gt;Inquiry Now&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;col-lg-6&quot;&gt;&lt;div class=&quot;preview-inner-img&quot;&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;!--===========  feature-images-wrapper  Start =============--&gt;&lt;div class=&quot;feature-images-wrapper position-relative&quot;&gt;&lt;/div&gt;&lt;!--===========  feature-images-wrapper  End =============--&gt;&lt;!--======== Preview Item Page section Start ============--&gt;&lt;!--======== Preview Item Page section End ============--&gt;&lt;!--======== Preview RTL section Start ============--&gt;&lt;!--======== Preview RTL section End ============--&gt;&lt;!--======= Layouts section Start =======--&gt;&lt;div class=&quot;layouts-section-wrap section-space--pt_100 section-space--pb_60&quot;&gt;&lt;div class=&quot;container-fluid&quot;&